<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRoute } from 'vue-router'
import { useProject } from '@/composables/useProject'
import { settings, lengthLabel } from '@/composables/useSettings'
import { distance } from '@/domain/geometry'
import SceneViewer from '@/components/SceneViewer.vue'
import AppIcon from '@/components/AppIcon.vue'
import NoticeBox from '@/components/NoticeBox.vue'
const route = useRoute(), id = computed(() => String(route.params.id)), { project, scenes, loading, error } = useProject(id), mode = ref<'orbit'|'top'|'walk'>('orbit'), wireframe = ref(false), grid = ref(settings.grid), panel = ref(false), viewer = ref<InstanceType<typeof SceneViewer>>(), pinIndex = ref(0)
function nextPin(): void { if (!project.value?.annotations.length) return; const pin = project.value.annotations[pinIndex.value % project.value.annotations.length]; viewer.value?.focusPin(pin); pinIndex.value++ }
</script>
<template><div class="viewer-page"><header class="viewer-header"><RouterLink :to="`/projects/${id}`" class="icon-button" aria-label="Back to space"><AppIcon name="back"/></RouterLink><div><strong>{{ project?.name || '3D viewer' }}</strong><small>{{ project?.scenes.some(s => s.source === 'sample') ? 'Illustrative sample' : 'Local 3D project' }}</small></div><div class="viewer-header-actions"><RouterLink :to="`/projects/${id}/edit`" class="icon-button" aria-label="Edit this space"><AppIcon name="edit"/></RouterLink><RouterLink :to="`/projects/${id}/export`" class="icon-button" aria-label="Export this space"><AppIcon name="download"/></RouterLink><button class="icon-button" :aria-expanded="panel" aria-label="Viewer information" @click="panel = !panel"><AppIcon name="info"/></button></div></header><div v-if="loading" class="loading-state">Loading 3D geometry…</div><NoticeBox v-if="error" kind="error">{{ error }}</NoticeBox><SceneViewer v-if="project && scenes.length" ref="viewer" :scenes="scenes" :annotations="project.annotations" :measurements="project.measurements" :mode="mode" :grid="grid" :wireframe="wireframe"/><div v-else-if="!loading" class="viewer-empty"><AppIcon name="cube" :size="54"/><h1>No 3D geometry yet.</h1><RouterLink :to="`/projects/${id}/scan`" class="btn btn-primary">Start a capture</RouterLink></div><div class="viewer-bottom"><div class="segmented viewer-mode"><button :class="{ active: mode === 'orbit' }" @click="mode = 'orbit'"><AppIcon name="cube" :size="18"/>Orbit</button><button :class="{ active: mode === 'top' }" @click="mode = 'top'"><AppIcon name="map" :size="18"/>Top</button><button :class="{ active: mode === 'walk' }" @click="mode = 'walk'"><AppIcon name="eye" :size="18"/>Walk</button></div><button v-if="project?.annotations.length" class="btn btn-primary" @click="nextPin"><AppIcon name="pin" :size="18"/>Next stop</button></div><aside v-if="panel && project" class="viewer-info card"><div class="section-heading"><h2>Explore your space</h2><button class="icon-button" aria-label="Close information" @click="panel = false"><AppIcon name="close"/></button></div><p>Drag to orbit. Pinch to zoom. In Walk mode, drag to look and use the direction buttons or WASD keys.</p><label class="switch-row"><span>Ground grid</span><input v-model="grid" type="checkbox" role="switch"></label><label class="switch-row"><span>Wireframe mesh</span><input v-model="wireframe" type="checkbox" role="switch"></label><h3 class="mt-4">Saved viewpoints</h3><button v-for="pin in project.annotations" :key="pin.id" class="pin-link" @click="viewer?.focusPin(pin)"><AppIcon name="pin" :size="17"/>{{ pin.label }}<AppIcon name="arrow" :size="16"/></button><p v-if="!project.annotations.length">Place hotspots in the editor to build a guided tour.</p><h3 class="mt-4">Measurements</h3><div v-for="m in project.measurements" :key="m.id" class="stat-pair"><span>{{ m.label }}</span><strong>≈ {{ lengthLabel(distance(m.a, m.b) * (project.scenes.find(s => s.id === m.sceneId)?.transform.scale || 1)) }}</strong></div><p class="fine-print">Dimensions are estimates, not survey measurements. Missing surfaces are not evidence of open space.</p></aside></div></template>
